<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/DB.php';$days=90;$dry=false;$quiet=false;$argv=isset($argv)?$argv:array();foreach(array_slice($argv,1)as $a){$a=(string)$a;if(strpos($a,'--days=')===0){$days=max(0,(int)substr($a,7));}elseif($a==='--dry'){$dry=true;}elseif($a==='--quiet'){$quiet=true;}}try{$pdo=Core\DB::pdo();if($days<=0){$total=(int)$pdo->query('SELECT COUNT(*) FROM app_api_logs')->fetchColumn();echo'保留期 0 = 不清理；当前流水 '.$total." 行\n";exit(0);}$before=(int)$pdo->query('SELECT COUNT(*) FROM app_api_logs')->fetchColumn();$st=$pdo->prepare('DELETE FROM app_api_logs WHERE created_at < DATE_SUB(NOW(), INTERVAL :d DAY) LIMIT 5000');$deleted=0;$guard=0;while($guard++<2000){if($dry){$cnt=(int)$pdo->query('SELECT COUNT(*) FROM app_api_logs WHERE created_at < DATE_SUB(NOW(), INTERVAL '.(int)$days.' DAY)')->fetchColumn();$deleted=$cnt;break;}$st->execute(array(':d'=>$days));$n=$st->rowCount();$deleted+=$n;if($n<5000){break;}usleep(50000);}$after=$dry?$before:($before-$deleted);if($quiet){echo($dry?'dry: 将删 ':'已删 ').$deleted." 行\n";}else{echo($dry?'[dry] 将删除':'清理完成，删除').' '.$deleted.' 行（保留最近 '.$days.' 天；'.$before.' → '.$after."）\n";}exit(0);}catch(\Throwable $e){fwrite(STDERR,'清理失败：'.$e->getMessage()."\n");exit(1);}